import itertools

def is_costas(perm):
    n = len(perm)
    vectors = set()
    for i in range(n):
        for j in range(i+1, n):
            dr = perm[j] - perm[i]
            dc = j - i
            if (dr, dc) in vectors:
                return False
            vectors.add((dr, dc))
    return True

# We need x[1]=1, meaning column 1 (0-indexed) has row 1
# So perm[1] = 1
n = 7
fixed_col = 1
fixed_row = 1

solutions = []
for perm in itertools.permutations(range(n)):
    if perm[fixed_col] == fixed_row:
        if is_costas(perm):
            solutions.append(list(perm))
            if len(solutions) >= 5:
                break

print(f"Found {len(solutions)} solutions")
for sol in solutions:
    print(sol)
